class Solution {
public:
    vector<int> exclusiveTime(int n, vector<string>& logs) {
        vector<int> res(n, 0);
        vector<int> st;
        int prevTime = 0;
        for (const string& log : logs) {
            int p1 = log.find(':');
            int p2 = log.find(':', p1 + 1);
            int fid = stoi(log.substr(0, p1));
            string action = log.substr(p1 + 1, p2 - p1 - 1);
            int ts = stoi(log.substr(p2 + 1));
            if (action == "start") {
                if (!st.empty()) res[st.back()] += ts - prevTime;
                st.push_back(fid);
                prevTime = ts;
            } else {
                res[st.back()] += ts - prevTime + 1;
                st.pop_back();
                prevTime = ts + 1;
            }
        }
        return res;
    }
};

class Solution {
    public int[] exclusiveTime(int n, java.util.List<String> logs) {
        int[] res = new int[n];
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        int prevTime = 0;
        for (String log : logs) {
            String[] parts = log.split(":");
            int fid = Integer.parseInt(parts[0]);
            String action = parts[1];
            int ts = Integer.parseInt(parts[2]);
            if (action.equals("start")) {
                if (!st.isEmpty()) res[st.peek()] += ts - prevTime;
                st.push(fid);
                prevTime = ts;
            } else {
                res[st.pop()] += ts - prevTime + 1;
                prevTime = ts + 1;
            }
        }
        return res;
    }
}

var exclusiveTime = function(n, logs) {
    const res = new Array(n).fill(0);
    const st = [];
    let prevTime = 0;
    for (const log of logs) {
        const [fidS, action, tsS] = log.split(':');
        const fid = Number(fidS);
        const ts = Number(tsS);
        if (action === 'start') {
            if (st.length > 0) res[st[st.length - 1]] += ts - prevTime;
            st.push(fid);
            prevTime = ts;
        } else {
            res[st.pop()] += ts - prevTime + 1;
            prevTime = ts + 1;
        }
    }
    return res;
};
